import json
import os

# Read all polymorph files and consolidate
all_data = []
polymorph_dir = "polymorph_data"

# Get all JSON files in the directory
for filename in os.listdir(polymorph_dir):
    if filename.endswith("_polymorphs.json"):
        filepath = os.path.join(polymorph_dir, filename)
        try:
            with open(filepath, 'r') as f:
                file_data = json.load(f)
                if isinstance(file_data, list):
                    all_data.extend(file_data)
        except Exception as e:
            print(f"Error reading {filename}: {e}")

filtered_data = all_data
